// ============================================================
// NODE: Load Cognitive Blueprint
// Maps to: CognitiveBlueprint, BlueprintIdentity, BlueprintMemory,
//          BlueprintPlanning, BlueprintValidation from the framework
// ============================================================

// Blueprint can come from chat input or use defaults
const input = $input.first().json;
const task = input.chatInput || input.task || 'Analyze the provided data';
const blueprintName = input.blueprint || 'research';

// Cognitive Blueprint definitions (equivalent to YAML configs)
const BLUEPRINTS = {
  research: {
    identity: {
      name: 'ResearchBot',
      version: '1.2.0',
      description: 'Answers research questions using calculation and reasoning',
      author: 'Cognitive Blueprint Framework'
    },
    goals: [
      'Answer user questions accurately using available tools',
      'Show step-by-step reasoning for all answers',
      'Cite the method used for each calculation'
    ],
    constraints: [
      'Never fabricate numbers or statistics',
      'Always validate mathematical results before reporting',
      'Do not answer questions outside your tool capabilities'
    ],
    tools: ['calculator', 'unit_converter', 'date_calculator', 'search_knowledge_base'],
    memory: {
      type: 'episodic',
      window_size: 12,
      summarize_after: 30
    },
    planning: {
      strategy: 'sequential',
      max_steps: 6,
      max_retries: 2,
      think_before_acting: true
    },
    validation: {
      require_reasoning: true,
      min_response_length: 20,
      forbidden_phrases: ["I don't know", "I cannot determine"]
    }
  },
  data_analyst: {
    identity: {
      name: 'DataAnalystBot',
      version: '2.0.0',
      description: 'Performs statistical analysis and data summarization',
      author: 'Cognitive Blueprint Framework'
    },
    goals: [
      'Compute descriptive statistics for given data',
      'Identify trends and anomalies',
      'Present findings clearly with numbers'
    ],
    constraints: [
      'Only work with numerical data',
      'Always report uncertainty when sample size is small (< 5 items)'
    ],
    tools: ['calculator', 'statistics_engine', 'list_sorter'],
    memory: {
      type: 'short_term',
      window_size: 6,
      summarize_after: 20
    },
    planning: {
      strategy: 'hierarchical',
      max_steps: 10,
      max_retries: 3,
      think_before_acting: true
    },
    validation: {
      require_reasoning: true,
      min_response_length: 30,
      forbidden_phrases: []
    }
  }
};

const blueprint = BLUEPRINTS[blueprintName] || BLUEPRINTS.research;

return [{
  json: {
    task,
    blueprint,
    blueprintName,
    // Initialize memory store
    memory: {
      history: [],
      summary: '',
      message_count: 0
    },
    // Execution metadata
    execution: {
      startTime: new Date().toISOString(),
      phases: []
    }
  }
}];

// ============================================================
// NODE: Tool Registry
// Maps to: ToolRegistry, ToolSpec, and all @registry.register tools
// Registers available tools and their implementations
// ============================================================

const data = $input.first().json;
const blueprint = data.blueprint;

// Tool Registry - maps to the ToolRegistry class
const TOOL_REGISTRY = {
  calculator: {
    name: 'calculator',
    description: 'Evaluates a safe mathematical expression',
    parameters: { expression: 'A math expression string' },
    returns: 'Numeric result as float'
  },
  unit_converter: {
    name: 'unit_converter',
    description: 'Converts between common units of measurement',
    parameters: {
      value: 'Numeric value to convert',
      from_unit: 'Source unit (km, miles, kg, lbs, celsius, fahrenheit, liters, gallons, meters, feet)',
      to_unit: 'Target unit'
    },
    returns: 'Converted value as string with units'
  },
  date_calculator: {
    name: 'date_calculator',
    description: 'Calculates days between two dates, or adds/subtracts days from a date',
    parameters: {
      operation: "'days_between' or 'add_days'",
      date1: 'Date string in YYYY-MM-DD format',
      date2: 'Second date or number of days'
    },
    returns: 'Result as string'
  },
  search_knowledge_base: {
    name: 'search_knowledge_base',
    description: 'Searches a knowledge base for information on a topic',
    parameters: { topic: 'Topic to look up' },
    returns: 'Short text summary'
  },
  statistics_engine: {
    name: 'statistics_engine',
    description: 'Computes descriptive statistics on a list of numbers',
    parameters: { numbers: 'Comma-separated list of numbers' },
    returns: 'JSON with mean, median, std_dev, min, max, count'
  },
  list_sorter: {
    name: 'list_sorter',
    description: 'Sorts a comma-separated list of numbers',
    parameters: { numbers: 'Comma-separated numbers', order: "'asc' or 'desc'" },
    returns: 'Sorted comma-separated list'
  }
};

// Build tool descriptions for allowed tools only
const allowedTools = blueprint.tools || [];
const toolDescriptions = allowedTools
  .filter(t => TOOL_REGISTRY[t])
  .map(t => {
    const spec = TOOL_REGISTRY[t];
    const params = Object.entries(spec.parameters)
      .map(([k, v]) => `${k}: ${v}`)
      .join(', ');
    return `- ${spec.name}(${params})\n  Description: ${spec.description}\n  Returns: ${spec.returns}`;
  })
  .join('\n\n');

return [{
  json: {
    ...data,
    toolRegistry: TOOL_REGISTRY,
    toolDescriptions,
    allowedTools
  }
}];

// ============================================================
// NODE: Build Planner Prompt
// Maps to: Planner._build_planner_prompt() and Planner.plan()
// Constructs the system and user prompts for plan generation
// ============================================================

const data = $input.first().json;
const bp = data.blueprint;

const plannerSystemPrompt = `You are ${bp.identity.name}, version ${bp.identity.version}.
${bp.identity.description}

## Your Goals:
${bp.goals.map(g => `  - ${g}`).join('\n')}

## Your Constraints:
${bp.constraints.map(c => `  - ${c}`).join('\n')}

## Available Tools:
${data.toolDescriptions}

## Planning Strategy: ${bp.planning.strategy}
## Max Steps: ${bp.planning.max_steps}

Given a user task, produce a JSON execution plan with this exact structure:
{
  "steps": [
    {
      "step_id": 1,
      "description": "What this step does",
      "tool": "tool_name or null if no tool needed",
      "tool_args": {"arg1": "value1"},
      "reasoning": "Why this step is needed"
    }
  ]
}

Rules:
- Only use tools listed above
- Set tool to null for pure reasoning steps
- Keep steps <= ${bp.planning.max_steps}
- Return ONLY valid JSON, no markdown fences`;

const plannerUserPrompt = `Create a plan to complete this task: ${data.task}`;

// Add memory context if available
let memoryContext = '';
if (data.memory && data.memory.summary) {
  memoryContext = `\n[Memory Summary]: ${data.memory.summary}`;
}

return [{
  json: {
    ...data,
    plannerSystemPrompt: plannerSystemPrompt + memoryContext,
    plannerUserPrompt
  }
}];

// ============================================================
// NODE: Parse Plan
// Maps to: Plan, PlanStep dataclasses
// Parses the LLM response into structured plan steps
// ============================================================

const data = $input.first().json;
let llmResponse = '';

// Handle Anthropic standalone node response format
// The Anthropic node returns { content: [{ type: 'text', text: '...' }] }
// or simplified output as { text: '...' } or { message: '...' }
if (data.content && Array.isArray(data.content)) {
  // Native Anthropic API response format
  const textParts = data.content.filter(c => c.type === 'text');
  llmResponse = textParts.map(c => c.text).join('');
} else if (data.text) {
  llmResponse = data.text;
} else if (data.message) {
  llmResponse = typeof data.message === 'string' ? data.message : JSON.stringify(data.message);
} else {
  llmResponse = JSON.stringify(data);
}

// Clean up response
llmResponse = llmResponse.replace(/```json/g, '').replace(/```/g, '').trim();

let plan;
try {
  plan = JSON.parse(llmResponse);
} catch (e) {
  // Fallback: create a single reasoning step
  plan = {
    steps: [{
      step_id: 1,
      description: 'Analyze and respond to the task',
      tool: null,
      tool_args: {},
      reasoning: 'Direct reasoning approach'
    }]
  };
}

// Retrieve the upstream data by reading from the workflow context
// We pass it forward from the planner prompt node
const upstreamData = $('Build Planner Prompt').first().json;

return [{
  json: {
    task: upstreamData.task,
    blueprint: upstreamData.blueprint,
    blueprintName: upstreamData.blueprintName,
    memory: upstreamData.memory,
    execution: upstreamData.execution,
    toolRegistry: upstreamData.toolRegistry,
    toolDescriptions: upstreamData.toolDescriptions,
    allowedTools: upstreamData.allowedTools,
    plan: {
      task: upstreamData.task,
      steps: plan.steps,
      strategy: upstreamData.blueprint.planning.strategy
    },
    currentStepIndex: 0,
    stepResults: []
  }
}];

// ============================================================
// NODE: Execute Step (Tool Router)
// Maps to: Executor.execute_plan() - the step execution loop
// Routes each plan step to the appropriate tool or reasoning
// ============================================================

const data = $input.first().json;
const stepIndex = data.currentStepIndex;
const steps = data.plan.steps;

if (stepIndex >= steps.length) {
  // All steps complete, go to synthesis
  return [{
    json: {
      ...data,
      allStepsComplete: true
    }
  }];
}

const step = steps[stepIndex];
let result = { step_id: step.step_id, success: false, output: '', tool_used: null, error: null };

try {
  if (step.tool && step.tool !== 'null') {
    // Tool execution - maps to registry.call()
    const args = step.tool_args || {};
    result.tool_used = step.tool;

    switch (step.tool) {
      case 'calculator': {
        const expr = args.expression || '';
        // Safe math evaluation
        const allowed = { Math, abs: Math.abs, round: Math.round, pow: Math.pow,
          sqrt: Math.sqrt, ceil: Math.ceil, floor: Math.floor, PI: Math.PI, E: Math.E,
          log: Math.log, sin: Math.sin, cos: Math.cos, tan: Math.tan };
        try {
          const fn = new Function(...Object.keys(allowed), `return (${expr})`);
          result.output = String(fn(...Object.values(allowed)));
          result.success = true;
        } catch (e) {
          result.output = `Error: ${e.message}`;
          result.error = e.message;
        }
        break;
      }
      case 'unit_converter': {
        const value = parseFloat(args.value);
        const from = (args.from_unit || '').toLowerCase();
        const to = (args.to_unit || '').toLowerCase();
        const conversions = {
          'km_miles': v => v * 0.621371,
          'miles_km': v => v * 1.60934,
          'kg_lbs': v => v * 2.20462,
          'lbs_kg': v => v / 2.20462,
          'celsius_fahrenheit': v => v * 9/5 + 32,
          'fahrenheit_celsius': v => (v - 32) * 5/9,
          'liters_gallons': v => v * 0.264172,
          'gallons_liters': v => v * 3.78541,
          'meters_feet': v => v * 3.28084,
          'feet_meters': v => v / 3.28084
        };
        const key = `${from}_${to}`;
        if (conversions[key]) {
          result.output = `${conversions[key](value).toFixed(4)} ${to}`;
          result.success = true;
        } else {
          result.output = `Conversion from ${from} to ${to} not supported`;
        }
        break;
      }
      case 'date_calculator': {
        const op = args.operation;
        const d1 = new Date(args.date1);
        if (op === 'days_between') {
          const d2 = new Date(args.date2);
          const days = Math.abs(Math.round((d2 - d1) / (1000 * 60 * 60 * 24)));
          result.output = `${days} days between ${args.date1} and ${args.date2}`;
        } else if (op === 'add_days') {
          const newDate = new Date(d1.getTime() + parseInt(args.date2) * 86400000);
          result.output = `${newDate.toISOString().split('T')[0]} (added ${args.date2} days to ${args.date1})`;
        }
        result.success = true;
        break;
      }
      case 'search_knowledge_base': {
        const topic = (args.topic || '').toLowerCase();
        const stubs = {
          'python': 'Python is a high-level programming language created by Guido van Rossum, released in 1991.',
          'machine learning': 'Machine learning is a subset of AI enabling systems to learn from data without explicit programming.',
          'eiffel tower': 'The Eiffel Tower is a wrought-iron lattice tower in Paris, France. Built in 1889, it stands 330 meters tall.',
          'contract law': 'Contract law governs legally binding agreements between parties, covering formation, performance, breach, and remedies.',
          'tort law': 'Tort law addresses civil wrongs that cause harm, including negligence, intentional torts, and strict liability.'
        };
        let found = 'No entry found. In production, this would query an external knowledge base.';
        for (const [key, val] of Object.entries(stubs)) {
          if (topic.includes(key)) { found = val; break; }
        }
        result.output = found;
        result.success = true;
        break;
      }
      case 'statistics_engine': {
        const nums = (args.numbers || '').split(',').map(x => parseFloat(x.trim())).filter(x => !isNaN(x));
        const n = nums.length;
        if (n === 0) { result.output = 'Error: No valid numbers provided'; break; }
        const mean = nums.reduce((a, b) => a + b, 0) / n;
        const sorted = [...nums].sort((a, b) => a - b);
        const mid = Math.floor(n / 2);
        const median = n % 2 ? sorted[mid] : (sorted[mid-1] + sorted[mid]) / 2;
        const stdDev = Math.sqrt(nums.reduce((s, x) => s + Math.pow(x - mean, 2), 0) / n);
        result.output = JSON.stringify({
          count: n,
          mean: Math.round(mean * 10000) / 10000,
          median: Math.round(median * 10000) / 10000,
          std_dev: Math.round(stdDev * 10000) / 10000,
          min: Math.min(...nums),
          max: Math.max(...nums),
          range: Math.max(...nums) - Math.min(...nums)
        }, null, 2);
        result.success = true;
        break;
      }
      case 'list_sorter': {
        const nums = (args.numbers || '').split(',').map(x => parseFloat(x.trim())).filter(x => !isNaN(x));
        const order = args.order || 'asc';
        nums.sort((a, b) => order === 'desc' ? b - a : a - b);
        result.output = nums.join(', ');
        result.success = true;
        break;
      }
      default:
        result.output = `Tool '${step.tool}' not found in registry`;
        result.error = 'Tool not found';
    }
  } else {
    // Pure reasoning step - needs LLM call
    // Mark for LLM reasoning (handled by next node)
    result.output = '__NEEDS_LLM_REASONING__';
    result.tool_used = null;
    result.success = true;
  }
} catch (e) {
  result.error = e.message;
  result.output = `Error: ${e.message}`;
}

const updatedResults = [...data.stepResults, result];

return [{
  json: {
    ...data,
    currentStep: step,
    currentStepResult: result,
    stepResults: updatedResults,
    currentStepIndex: stepIndex + 1,
    needsLLMReasoning: result.output === '__NEEDS_LLM_REASONING__',
    allStepsComplete: (stepIndex + 1) >= steps.length
  }
}];

// ============================================================
// NODE: Build Reasoning Prompt
// Maps to: Executor reasoning branch (when step.tool is null)
// ============================================================

const data = $input.first().json;
const step = data.currentStep;
const bp = data.blueprint;

const contextText = data.stepResults
  .filter(r => r.output !== '__NEEDS_LLM_REASONING__')
  .map(r => `Step ${r.step_id} result: ${r.output}`)
  .join('\n');

const userPrompt = contextText
  ? `Previous results:\n${contextText}\n\nNow complete this step: ${step.description}\nReasoning hint: ${step.reasoning}`
  : `Complete this step: ${step.description}\nReasoning hint: ${step.reasoning}`;

const systemPrompt = `You are ${bp.identity.name}. ${bp.identity.description}. Constraints: ${bp.constraints.join('; ')}`;

return [{
  json: {
    ...data,
    reasoningSystemPrompt: systemPrompt,
    reasoningUserPrompt: userPrompt
  }
}];

// ============================================================
// NODE: Update Reasoning Result
// Updates the step result with LLM reasoning output
// ============================================================

const upstreamData = $('Build Reasoning Prompt').first().json;
const llmData = $input.first().json;

let reasoningOutput = '';

// Handle Anthropic standalone node response format
if (llmData.content && Array.isArray(llmData.content)) {
  const textParts = llmData.content.filter(c => c.type === 'text');
  reasoningOutput = textParts.map(c => c.text).join('');
} else if (llmData.text) {
  reasoningOutput = llmData.text;
} else if (llmData.message) {
  reasoningOutput = typeof llmData.message === 'string' ? llmData.message : JSON.stringify(llmData.message);
} else {
  reasoningOutput = JSON.stringify(llmData);
}

// Update the last step result with the reasoning output
const results = [...upstreamData.stepResults];
results[results.length - 1] = {
  ...results[results.length - 1],
  output: reasoningOutput,
  success: true
};

return [{
  json: {
    task: upstreamData.task,
    blueprint: upstreamData.blueprint,
    blueprintName: upstreamData.blueprintName,
    memory: upstreamData.memory,
    execution: upstreamData.execution,
    toolRegistry: upstreamData.toolRegistry,
    toolDescriptions: upstreamData.toolDescriptions,
    allowedTools: upstreamData.allowedTools,
    plan: upstreamData.plan,
    currentStepIndex: upstreamData.currentStepIndex,
    stepResults: results,
    allStepsComplete: upstreamData.allStepsComplete
  }
}];

// ============================================================
// NODE: Build Synthesis Prompt
// Maps to: Executor._synthesize()
// Combines all step results into a final answer
// ============================================================

const data = $input.first().json;
const bp = data.blueprint;

const stepsSummary = data.stepResults
  .map(r => `Step ${r.step_id} (${r.success ? 'SUCCESS' : 'FAILED'}): ${(r.output || '').substring(0, 300)}`)
  .join('\n');

const synthesisUserPrompt = `Original task: ${data.task}\n\nStep results:\n${stepsSummary}\n\nProvide a clear, complete final answer. Integrate all step results.`;

const synthesisSystemPrompt = `You are ${bp.identity.name}. ` +
  (bp.validation.require_reasoning ? 'Always show your reasoning. ' : '') +
  `Goals: ${bp.goals.join('; ')}`;

// Add memory context
let memoryMessages = [];
if (data.memory && data.memory.summary) {
  memoryMessages.push({ role: 'system', content: `[Memory Summary]: ${data.memory.summary}` });
}

return [{
  json: {
    ...data,
    synthesisSystemPrompt,
    synthesisUserPrompt,
    memoryMessages
  }
}];

// ============================================================
// NODE: Validation Engine
// Maps to: Validator.validate() and ValidationResult
// Validates the final answer against blueprint rules
// ============================================================

const synthesisData = $('Build Synthesis Prompt').first().json;
const llmData = $input.first().json;

let finalAnswer = '';

// Handle Anthropic standalone node response format
if (llmData.content && Array.isArray(llmData.content)) {
  const textParts = llmData.content.filter(c => c.type === 'text');
  finalAnswer = textParts.map(c => c.text).join('');
} else if (llmData.text) {
  finalAnswer = llmData.text;
} else if (llmData.message) {
  finalAnswer = typeof llmData.message === 'string' ? llmData.message : JSON.stringify(llmData.message);
} else {
  finalAnswer = JSON.stringify(llmData);
}

const bp = synthesisData.blueprint;
const v = bp.validation;
const issues = [];

// Rule 1: Minimum response length
if (finalAnswer.length < v.min_response_length) {
  issues.push(`Response too short: ${finalAnswer.length} chars (min: ${v.min_response_length})`);
}

// Rule 2: Forbidden phrases
const answerLower = finalAnswer.toLowerCase();
for (const phrase of (v.forbidden_phrases || [])) {
  if (answerLower.includes(phrase.toLowerCase())) {
    issues.push(`Forbidden phrase detected: '${phrase}'`);
  }
}

// Rule 3: Reasoning indicators
if (v.require_reasoning) {
  const indicators = ['because', 'therefore', 'since', 'step', 'first',
    'result', 'calculated', 'computed', 'found that', 'analysis', 'based on'];
  if (!indicators.some(ind => answerLower.includes(ind))) {
    issues.push('Response lacks visible reasoning or explanation');
  }
}

const validationResult = {
  passed: issues.length === 0,
  issues,
  score: Math.max(0.0, 1.0 - issues.length * 0.25)
};

// Update memory
const memory = synthesisData.memory || { history: [], summary: '', message_count: 0 };
memory.history.push({
  role: 'user',
  content: synthesisData.task,
  timestamp: new Date().toISOString()
});
memory.history.push({
  role: 'assistant',
  content: finalAnswer,
  timestamp: new Date().toISOString()
});
memory.message_count = memory.history.length;

// Check if memory compression needed (maps to MemoryManager._compress_memory)
const memoryConfig = bp.memory;
if (memory.history.length > (memoryConfig.summarize_after || 20)) {
  const toCompress = memory.history.slice(0, -memoryConfig.window_size);
  memory.history = memory.history.slice(-memoryConfig.window_size);
  const compressedText = toCompress.map(e => `${e.role}: ${(e.content || '').substring(0, 200)}`).join('\n');
  memory.summary += ` [Compressed ${toCompress.length} messages]`;
}

return [{
  json: {
    task: synthesisData.task,
    blueprint: bp,
    blueprintName: synthesisData.blueprintName,
    plan: synthesisData.plan,
    stepResults: synthesisData.stepResults,
    finalAnswer,
    validation: validationResult,
    memory,
    execution: {
      ...synthesisData.execution,
      endTime: new Date().toISOString(),
      phases: ['planning', 'execution', 'synthesis', 'validation']
    }
  }
}];

// ============================================================
// NODE: Format Response
// Maps to: RuntimeAgent._display_answer() and _display_plan()
// Builds the final response for the n8n Chat widget
// The Chat Trigger expects { output: string } to display in chat
// ============================================================

const data = $input.first().json;

// Build a readable chat response from the structured data
const stepDetails = data.stepResults
  .map(r => `  Step ${r.step_id} [${r.tool_used || 'reasoning'}]: ${(r.output || '').substring(0, 200)}`)
  .join('\n');

const validationNote = data.validation.passed
  ? ''
  : `\n\n---\n_Validation notes: ${data.validation.issues.join('; ')}_`;

const chatOutput = `${data.finalAnswer}${validationNote}`;

return [{
  json: {
    output: chatOutput
  }
}];

// ============================================================
// NODE: Retry Handler
// Maps to: blueprint.planning.max_retries logic
// Handles validation failures by re-planning with feedback
// ============================================================

const data = $input.first().json;
const retryCount = (data.execution.retryCount || 0) + 1;
const maxRetries = data.blueprint.planning.max_retries;

if (retryCount > maxRetries) {
  // Max retries exceeded - return answer with warning via chat output
  const warningAnswer = data.finalAnswer + '\n\n---\n_Note: Validation issues were detected but max retries exceeded. Issues: ' + data.validation.issues.join('; ') + '_';

  return [{
    json: {
      output: warningAnswer
    }
  }];
}

// Retry: update task with validation feedback and loop back to planner
return [{
  json: {
    task: data.task + '\n\nIMPORTANT: Previous attempt had these issues: ' + data.validation.issues.join('; ') + '. Please address them.',
    blueprint: data.blueprint,
    blueprintName: data.blueprintName,
    memory: data.memory,
    execution: { ...data.execution, retryCount },
    toolRegistry: data.toolRegistry || {},
    toolDescriptions: data.toolDescriptions || '',
    allowedTools: data.allowedTools || []
  }
}];
